26	void ggZZcapture(const std::string& label, int h34, int h56,
27	                 int j1, int j2, int j3, int j4, int j5, int j6,
28	                 std::complex<double>& amp0, std::complex<double>& amp2,
29	                 std::complex<double>& amp4) {
30	
31	    const int imt0 = 1, imt2 = 2, imt4 = 3;
32	    const int ipp = 1, imp = 2;
33	    int htag, ltag = 0, itag = 0;
34	
35	    if (first) {
36	        std::fill(res.data, res.data + res.ni * res.nj * res.nk * res.nl, czip);
37	        first = false;
38	    }
39	
40	    htag = -1;
41	
42	    // Canonical permutation:  1 2 3 4 5 6
43	    if ((j1 == 1) && (j2 == 2) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
44	        if ((label == "1x2") && (h34 == 1) && (h56 == 1)) {
45	            htag = imp; ltag = 3; itag = c1_2;
46	        }
47	        if ((label == "1x2pp") && (h34 == 1) && (h56 == 1)) {
48	            htag = ipp; ltag = 3; itag = c1_2;
49	        }
50	        if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
51	            htag = imp; ltag = 3; itag = c1_34;
52	        }
53	        if ((label == "1x34pp") && (h34 == 1) && (h56 == 1)) {
54	            htag = ipp; ltag = 3; itag = c1_34;
55	        }
56	        if ((label == "12x34") && (h34 == 1) && (h56 == 1)) {
57	            htag = imp; ltag = 3; itag = c12_34;
58	        }
59	        if ((label == "12x34pp") && (h34 == 1) && (h56 == 1)) {
60	            htag = ipp; ltag = 3; itag = c12_34;
61	        }
62	        if ((label == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
63	            htag = imp; ltag = 4; itag = d1_34_2;
64	        }
65	        if ((label == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
66	            htag = ipp; ltag = 4; itag = d1_34_2;
67	        }
68	        if ((label == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
69	            htag = ipp; ltag = 4; itag = d2_1_34;
70	        }
71	        if ((label == "2x1x34") && (h34 == 1) && (h56 == 1)) {
72	            htag = imp; ltag = 4; itag = d2_1_34;
73	        }
74	        if ((label == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
75	            htag = imp; ltag = 4; itag = d6_2_1_34;
76	        }
77	        if ((label.size() >= 5) && (label.substr(0, 5) == "bubmp") && (h34 == 1) && (h56 == 1)) {
78	            htag = imp; ltag = 2;
79	            itag = (label.size() >= 6) ? (label[5] - '0') : 0;
80	        }
81	        if ((label.size() >= 5) && (label.substr(0, 5) == "bubpp") && (h34 == 1) && (h56 == 1)) {
82	            htag = ipp; ltag = 2;
83	            itag = (label.size() >= 6) ? (label[5] - '0') : 0;
84	        }
85	    }
86	
87	    // Permute 1 and 2:  2 1 3 4 5 6
88	    if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
89	        if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
90	            htag = imp; ltag = 3; itag = c2_34;
91	            if (amp0 != czip) amp0 = std::conj(amp0);
92	            if (amp2 != czip) amp2 = std::conj(amp2);
93	            if (amp4 != czip) amp4 = std::conj(amp4);
94	        }
95	        if ((label == "1x34pp") && (h34 == 1) && (h56 == 1)) {
96	            htag = ipp; ltag = 3; itag = c2_34;
97	            if (amp0 != czip) amp0 = std::conj(amp0);
98	            if (amp2 != czip) amp2 = std::conj(amp2);
99	            if (amp4 != czip) amp4 = std::conj(amp4);
100	        }
101	        if ((label == "2x1x34") && (h34 == 1) && (h56 == 1)) {
102	            htag = imp; ltag = 4; itag = d1_2_34;
103	            if (amp0 != czip) amp0 = std::conj(amp0);
104	            if (amp2 != czip) amp2 = std::conj(amp2);
105	            if (amp4 != czip) amp4 = std::conj(amp4);
106	        }
107	        if ((label == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
108	            htag = imp; ltag = 4; itag = d6_1_2_34;
109	            if (amp0 != czip) amp0 = std::conj(amp0);
110	            if (amp2 != czip) amp2 = std::conj(amp2);
111	            if (amp4 != czip) amp4 = std::conj(amp4);
112	        }
113	    }
114	
115	    // Permute 3,4 and 5,6:  1 2 5 6 3 4
116	    if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
117	        if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
118	            htag = imp; ltag = 3; itag = c1_56;
119	        }
120	        if ((label == "1x34pp") && (h34 == 1) && (h56 == 1)) {
121	            htag = ipp; ltag = 3; itag = c1_56;
122	        }
123	        if ((label == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
124	            htag = ipp; ltag = 4; itag = d1_2_34;
125	        }
126	    }
127	
128	    // Permute 1,3,4 and 2,5,6:  2 1 5 6 3 4
129	    if ((j1 == 2) && (j2 == 1) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
130	        if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
131	            htag = imp; ltag = 3; itag = c2_56;
132	            if (amp0 != czip) amp0 = std::conj(amp0);
133	            if (amp2 != czip) amp2 = std::conj(amp2);
134	            if (amp4 != czip) amp4 = std::conj(amp4);
135	        }
136	        if ((label == "1x34pp") && (h34 == 1) && (h56 == 1)) {
137	            htag = ipp; ltag = 3; itag = c2_56;
138	            if (amp0 != czip) amp0 = std::conj(amp0);
139	            if (amp2 != czip) amp2 = std::conj(amp2);
140	            if (amp4 != czip) amp4 = std::conj(amp4);
141	        }
142	    }
143	
144	    if (htag < 0) {
145	        return;
146	    }
147	
148	    // Assign results
149	    res(htag, ltag, itag, imt0) = amp0; // @coverage-probe
150	    res(htag, ltag, itag, imt2) = amp2;
151	    res(htag, ltag, itag, imt4) = amp4;
152	
153	    if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8)
154	        res(htag, ltag, itag, imt0) = czip;
155	    if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8)
156	        res(htag, ltag, itag, imt2) = czip;
157	    if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8)
158	        res(htag, ltag, itag, imt4) = czip;
159	
160	    return;
161	}
162	
163	extern "C" {
164	    void ggZZcapture_wrapper(const char* label,
165	                             int* h34, int* h56,
166	                             int* j1, int* j2, int* j3, int* j4, int* j5, int* j6,
167	                             std::complex<double>* amp0,
168	                             std::complex<double>* amp2,
169	                             std::complex<double>* amp4) {
170	        std::string slabel(label);
171	        ggZZcapture(slabel, *h34, *h56, *j1, *j2, *j3, *j4, *j5, *j6,
172	                    *amp0, *amp2, *amp4);
173	    }
174	}
