// conventions.  Called twice from ZZbox1LL with za/zb swapped to fill the
// full set of helicity coefficients.
static void ZZbox1LLcore(int j1, int j2, int j3, int j4, int j5, int j6,
                          FArray2D<std::complex<double>>& za,
                          FArray2D<std::complex<double>>& zb,
                          double mt,
